/// Layer-225 schema constant lookup used by the regression test:
/// maps a constructors.rs name to the generated `*_ID` value.
#[cfg(test)]
pub(crate) fn gen_const(name: &str) -> Option<u32> {
    use chat_gen as c;
    use input_gen as i;
    use message_gen as m;
    use user_gen as u;
    use dialog_gen as d;
    use reply_markup_gen as rm;
    Some(match name {
        "USER" => u::USER_ID,
        "USER_EMPTY" => u::USER_EMPTY_ID,
        "CHAT" => c::CHAT_ID,
        "CHAT_EMPTY" => c::CHAT_EMPTY_ID,
        "CHAT_FORBIDDEN" => c::CHAT_FORBIDDEN_ID,
        "CHANNEL" => c::CHANNEL_ID,
        "MESSAGE" => m::MESSAGE_ID,
        "MESSAGE_EMPTY" => m::MESSAGE_EMPTY_ID,
        "MESSAGE_SERVICE" => m::MESSAGE_SERVICE_ID,
        "MESSAGE_MEDIA_PHOTO" => m::MESSAGE_MEDIA_PHOTO_ID,
        "MESSAGE_MEDIA_DOCUMENT" => m::MESSAGE_MEDIA_DOCUMENT_ID,
        "DIALOG" => d::DIALOG_ID,
        "PEER_USER" => peer_gen::PEER_USER_ID,
        "PEER_CHAT" => peer_gen::PEER_CHAT_ID,
        "PEER_CHANNEL" => peer_gen::PEER_CHANNEL_ID,
        "INPUT_PEER_USER" => i::INPUT_PEER_USER_ID,
        "INPUT_PEER_CHAT" => i::INPUT_PEER_CHAT_ID,
        "INPUT_PEER_CHANNEL" => i::INPUT_PEER_CHANNEL_ID,
        "INPUT_PEER_SELF" => i::INPUT_PEER_SELF_ID,
        "INPUT_USER" => i::INPUT_USER_ID,
        "INPUT_USER_SELF" => i::INPUT_USER_SELF_ID,
        "INPUT_CHANNEL" => i::INPUT_CHANNEL_ID,
        "INPUT_FILE" => i::INPUT_FILE_ID,
        "INPUT_FILE_BIG" => i::INPUT_FILE_BIG_ID,
        "INPUT_DOCUMENT" => i::INPUT_DOCUMENT_ID,
        "INPUT_DOCUMENT_EMPTY" => i::INPUT_DOCUMENT_EMPTY_ID,
        "KEYBOARD_BUTTON" => rm::KEYBOARD_BUTTON_ID,
        "USER_STATUS_ONLINE" => u::USER_STATUS_ONLINE_ID,
        "USER_STATUS_OFFLINE" => u::USER_STATUS_OFFLINE_ID,
        "USER_PROFILE_PHOTO" => u::USER_PROFILE_PHOTO_ID,
        "PEER_NOTIFY_SETTINGS" => c::PEER_NOTIFY_SETTINGS_ID,
        "AUTH_AUTHORIZATION" => m::AUTH_AUTHORIZATION_ID,
        "AUTH_SIGN_IN" => m::AUTH_SIGN_IN_ID,
        _ => return None,
    })
}
